    "description": "中新社福建平潭8月1日电 (记者 闫旭)2026福建省城市足球联赛岚台交流赛1日晚在平潭鸣哨开赛，台湾劲凤足球队与2026福建省城市足球联赛(“闽超”)平潭队对阵。最终，平潭队以2：1的比分战胜台湾劲凤足球队。",
    "content": "中新社福建平潭8月1日电 (记者 闫旭)2026福建省城市足球联赛岚台交流赛1日晚在平潭鸣哨开赛，台湾劲凤足球队与2026福建省城市足球联赛(“闽超”)平潭队对阵。最终，平潭队以2：1的比分战胜台湾劲凤足球队。"
