    "content": "新华社德黑兰8月1日电（记者陈霄 沙达提）据伊朗迈赫尔通讯社1日晚报道，伊朗外交部长阿拉格齐当天通过中间方警告美国不要采取任何“冒险行动”。 报道说，阿拉格齐当天分别同巴基斯坦陆军参谋长穆尼尔、土耳其外交部长费丹和沙特外交大臣费萨尔通电话，就地区局势以及美国和以色列相关行动交换意见。 报道称，阿拉格齐在同穆尼尔和费丹通话时，警告美国不要采取任何“冒险行动”，并表示伊朗已做好维护国家主权、领土完整和国家安全的充分准备，将对任何侵犯行为作出坚决回应。 在与费萨尔通话时，阿拉格齐说，来自美国和以色列的任何侵略或敌对行动，…"
