    "content": "“海量发掘资料与科学数据为人工智能技术提供了沃土，未来科技考古的重大突破，需要人工智能发挥关键作用。”7月31日至8月1日在京举行的科技考古与文化遗产保护国际学术研讨会上，中国科学院大学人文学院教授王昌燧的一番话，引发与会学者的共鸣。 专家表示，考古学虽长期归为人文学科，但科技考古的前沿探索早已突破学科边界，培养文理兼通的复合型人才是当前学科建设亟待回应的紧迫课题，也是迈向未来的必然选择。 科技考古与文化遗产保护国际学术研讨会海报。（主办方供图） 在这场由中国社会科学院主办的学术研讨会上，来自十余个国家的近300位…"
