    "description": "据气象部门预报，8月1日至3日，重庆部分地区有大到暴雨、局地大暴雨，山洪和地质灾害、中小河流洪水等灾害风险较高。根据《国家防汛抗旱应急预案》及有关规定，国家防总、应急管理部决定于8月1日22时针对重庆启动防汛四级应急响应。",
    "content": "据气象部门预报，8月1日至3日，重庆部分地区有大到暴雨、局地大暴雨，山洪和地质灾害、中小河流洪水等灾害风险较高。根据《国家防汛抗旱应急预案》及有关规定，国家防总、应急管理部决定于8月1日22时针对重庆启动防汛四级应急响应。"
