    "description": "新华社合肥8月1日电（记者郭晨）记者从安徽省亳州市相关部门了解到，8月1日晚，亳州市谯城区发生一起火灾，2人死亡。 据了解，8月1日19时左右亳州市消防部门接警，在该市谯城区城父镇一处民房内发生火灾，初步造成2人死亡。19时21分左右，明火被扑灭。目前，火灾原因还在进一步调查。",
    "content": "新华社合肥8月1日电（记者郭晨）记者从安徽省亳州市相关部门了解到，8月1日晚，亳州市谯城区发生一起火灾，2人死亡。 据了解，8月1日19时左右亳州市消防部门接警，在该市谯城区城父镇一处民房内发生火灾，初步造成2人死亡。19时21分左右，明火被扑灭。目前，火灾原因还在进一步调查。"
