    "description": "网络之上，一句过激评论、一段剪辑画面、一张AI合成影像，都可能酿成网络暴力，不少人认为网上随意发布他人视频只是娱乐，打字跟风骂几句不用负责，实则不然。近期《中华人民共和国反网络暴力法(征求意见稿)》面向社会征求意见。如何区分正常讨论与网暴？遭遇侵害该怎样维权？律师告诉你面对“网暴”不必沉默。(记者 吕杨)",
