    "description": "央广网昆明7月31日消息(记者 赵贝贝 见习记者 冯宜)金沙江一路奔腾，在云南境内蜿蜒千余公里，串联起雪山峡谷、干热河谷和港口码头，也见证着长江上游生态保护与绿色发展的时代变迁。长江经济带发展战略实施以来，云南坚持共抓大保护、不搞大开发，持续筑牢长江上游生态安全屏障，畅通通江达海开放通道。从丽江石鼓守护一湾碧水，到元谋干热河谷重披绿装，再到昭通水富港联通长江黄金水道，一幅生态美、产业兴、百姓富的发展画卷正沿江徐徐铺展。",
    "content": "央广网昆明7月31日消息(记者 赵贝贝 见习记者 冯宜)金沙江一路奔腾，在云南境内蜿蜒千余公里，串联起雪山峡谷、干热河谷和港口码头，也见证着长江上游生态保护与绿色发展的时代变迁。长江经济带发展战略实施以来，云南坚持共抓大保护、不搞大开发，持续筑牢长江上游生态安全屏障，畅通通江达海开放通道。从丽江石鼓守护一湾碧水，到元谋干热河谷重披绿装，再到昭通水富港联通长江黄金水道，一幅生态美、产业兴、百姓富的发展画卷正沿江徐徐铺展。"
