    "author": "江夏堂",
    "description": "电影《乱世佳人》中，斯嘉丽的父亲对她说：“土地是世界上唯一值得你去为之工作、为之战斗、为之牺牲的东西，因为它是唯一永恒的东西。”斯嘉丽颠沛流离，直到一无所有才读懂这句话。 最近在一档综艺里，脱口秀演员房主任，用一场刷屏的户籍风波，复刻了这份对土地的执念，却走向了完全相反的结局。 派出所窗口失控的争执、全网的性别论战、三个月停演的处罚、最后落户沈阳商品房的收尾。大众沉溺于“农村离异女性”“公众人物失德”的二元对立，忽略最核心的底色：她争户…",
    "content": "电影《乱世佳人》中，斯嘉丽的父亲对她说：“土地是世界上唯一值得你去为之工作、为之战斗、为之牺牲的东西，因为它是唯一永恒的东西。”斯嘉丽颠沛流离，直到一无所有才读懂这句话。 最近在一档综艺里，脱口秀演员房主任，用一场刷屏的户籍风波，复刻了这份对土地的执念，却走向了完全相反的结局。 派出所窗口失控的争执、全网的性别论战、三个月停演的处罚、最后落户沈阳商品房的收尾。大众沉溺于“农村离异女性”“公众人物失德”的二元对立，忽略最核心的底色：她争户口、拒集体户、执意自立户主，这套动作底下压着的，是即将到来的二轮土地延包的财产权…"
