    "content": "（本文首发于南方人物周刊） 南方人物周刊特约撰稿 朱江明 责任编辑：李屾淼 2024年8月4日，某未公开地点，乌克兰总统泽连斯基站在该国接收的首批F-16战斗机前 （视觉中国/图） 2026年7月8日，乌克兰使用F-16战机在空战中击落俄罗斯4.5代Su-35战机。这一战例在7月9日被乌克兰方面公布，7月中旬美军参谋长联席会议主席丹·凯恩在国会听证会上公开证实此事。 这次击落对外界的震惊程度，不亚于2025年印巴空战中巴基斯坦的歼10战机成功在空中猎杀印度阵风战机的影响。舆论尤其对俄制战机的设计理念和实用性产生了巨…"
