    "content": "记者8月1日从国投集团雅砻江流域水电开发有限公司获悉，雅砻江流域水风光一体化基地约2300万千瓦投产装机已全面投入迎峰度夏电力保供。目前，流域梯级水电联合运行蓄能达177.7亿千瓦时，同比增加9.5亿千瓦时，为电网顶峰供电储备了充足水能。 雅砻江流域水风光一体化基地集中控制中心迎峰度夏值班现场。（受访者供图） 目前，雅砻江流域水风光一体化基地已建成两河口、锦屏一级、二滩三座大型调节水库，总库容249亿立方米，调节库容148亿立方米，约占四川省大型水库总调节库容的51%。依托锦苏直流、雅湖直流等特高压输电工程，雅砻江…"
