    "description": "故宫午门与端门之间，驻扎着大众所熟知的“最帅天团”——中国人民解放军仪仗司礼大队。红墙青砖、晨露朝风，他们日复一日迎着天安门的日出，守护五星红旗与太阳一同升起。他们曾踏过长安街阅兵场，执行过迎送外国元首、海外援训等重大任务，在万众瞩目下扛起家国荣光。",
    "content": "故宫午门与端门之间，驻扎着大众所熟知的“最帅天团”——中国人民解放军仪仗司礼大队。红墙青砖、晨露朝风，他们日复一日迎着天安门的日出，守护五星红旗与太阳一同升起。他们曾踏过长安街阅兵场，执行过迎送外国元首、海外援训等重大任务，在万众瞩目下扛起家国荣光。"
