    "pub_date": "2026-08-01 21:43:33",
    "author": "",
    "description": "央视网消息(新闻联播)：近年来，我国不断提升医保管理服务水平，加快打通医保基金即时结算堵点，进一步减轻群众就医负担。国家医保局最新统计显示，今年1—5月，全国跨省异地就医直接结算1.47亿人次，涉及医疗总费用1503亿元，减少群众垫付资金886亿元。",
    "content": "央视网消息(新闻联播)：近年来，我国不断提升医保管理服务水平，加快打通医保基金即时结算堵点，进一步减轻群众就医负担。国家医保局最新统计显示，今年1—5月，全国跨省异地就医直接结算1.47亿人次，涉及医疗总费用1503亿元，减少群众垫付资金886亿元。"
