    "description": "新华社北京8月1日电 希腊近来多地燃起野火，其中一场野火借助强风8月1日蔓延至首都雅典西北方向约60公里处，情况最为危急。 据德新社报道，人们从雅典可以清晰看到野火燃烧产生的滚滚浓烟。1日上午，作为预防措施，受该火场波及的多个村庄已疏散居民。希腊消防部门在社交媒体说，已向这处火场派遣超过300名消防员和志愿者、92辆消防车、18架飞机和7架直升机灭火。 当地媒体报道，希腊海岸警卫队和消防部门1日在著名度假地杰梅诺港一处海滩用船救出12名…",
    "content": "新华社北京8月1日电 希腊近来多地燃起野火，其中一场野火借助强风8月1日蔓延至首都雅典西北方向约60公里处，情况最为危急。 据德新社报道，人们从雅典可以清晰看到野火燃烧产生的滚滚浓烟。1日上午，作为预防措施，受该火场波及的多个村庄已疏散居民。希腊消防部门在社交媒体说，已向这处火场派遣超过300名消防员和志愿者、92辆消防车、18架飞机和7架直升机灭火。 当地媒体报道，希腊海岸警卫队和消防部门1日在著名度假地杰梅诺港一处海滩用船救出12名受困人员。该地区至少10座房屋被烧毁。 这是7月29日在希腊克里特岛雷西姆诺地区…"
