    "description": "7月31日，苏州交警联合多部门在全国率先上线外卖骑手“红灯停表”配时延长的交管新措。记者实地采访发现，多名骑手接单途中在路口等红灯时，骑手手机显示红灯倒计时读秒，同步提示“红灯停一停，正在记录等灯时长”，配送结束后弹窗显示等红灯累计时间。以制度减压促安全，让骑手们守法不吃亏。 记者：李光正、杨绍功 部分素材来源：苏州广电 新华社音视频部制作",
