    "content": "新华社西宁8月1日电（记者 解统强）由中国绿发投资集团有限公司青海分公司负责建设的20兆瓦飞轮储能项目，8月1日在青海省海西蒙古族藏族自治州格尔木市开工建设，这个项目采用多类型飞轮协同技术，可实现毫秒级响应，建成后将助推我国新型储能多元化、高质量发展。 据介绍，飞轮储能技术主要是利用电机驱动飞轮升速储能、飞轮降速带动电机发电释能的大功率物理储能技术，具有高转动惯量、高功率密度、快响应等特点。规模化飞轮储能阵列，可提供新型电力系统惯量支撑保障和调频需求，助力构建高比例新能源的新型电力系统。 此次开工建设的20兆瓦飞轮…"
