    "content": "新华社乌鲁木齐8月1日电（记者潘莹、周生斌）在中国人民解放军建军99周年之际，承载新疆红色历史、传承戍边精神的新疆革命军事馆8月1日举行开馆仪式。 新疆革命军事馆位于新疆乌鲁木齐市，主体建筑面积1万平方米，展览面积6500平方米。展品包括2.3万余件（套）馆藏文物、1500余件（幅）文献图片，以及数十组主题雕塑、复原场景、油画浮雕等，全方位立体展现中国共产党领导新疆各族群众革命斗争的光辉历程。 该馆共设置1个基本陈列、2个专题陈列和1个专题展区。其中，基本陈列主题为“红星耀天山”中国共产党领导新疆革命军事史，分4个…"
