    "description": "随着各大院校进入开学季，铁路将迎来学生旅客出行高峰，铁路12306上线了新生专属购票通道。2026级新生旅客在开车前第20天至第17天，预约乘车日期为8月17日至9月14日的一次单程车票，可按规定享受学生优惠票价。 记者：司晓帅 新华社音视频部制作",
    "content": "随着各大院校进入开学季，铁路将迎来学生旅客出行高峰，铁路12306上线了新生专属购票通道。2026级新生旅客在开车前第20天至第17天，预约乘车日期为8月17日至9月14日的一次单程车票，可按规定享受学生优惠票价。 记者：司晓帅 新华社音视频部制作"
