    "content": "新华社武汉8月1日电（记者乐文婉）我国首台掘爆机“翔龙号”1日在湖北省武汉市中铁科工江夏制造基地下线。这款装备融合掘进法与钻爆法两大主流工法，填补了复杂地质隧道一体化施工装备领域的空白。 “翔龙号”由清华大学与中铁科工集团联合研制，整机长70米，开挖直径达4.55米，中心刀盘直径1.2米，整机重量约400吨。该装备创新采用空心刀盘结构，依靠空心刀盘、中心刀盘协同运作，可灵活切换“前爆后掘”“前掘后爆”“全断面掘进”等多种作业模式，融合超前钻爆预处理、机械化连续开挖双重优势。 8月1日，在湖北省武汉市中铁科工江夏制造…"
