    "author": "南方周末记者 周小铃",
    "description": "有了“身份证”，就能看到房子的“前世今生”。 南方周末记者 周小铃 责任编辑：张玥 全国城乡房屋建筑共3.54亿栋，其中城镇房屋0.47亿栋，农村房屋3.07亿栋。视觉中国/图 在7月的杭州，如果你买了新房，水、电、气开户的时候，不用再跑三家单位、填三张表了，手机上点一下，授权信息推送即可。 这背后是“房屋建筑统一代码”的建成。购房人在“e房通”平台完成合同网签后，通过“一码串联”，房屋信息会共享到水、电、气等部门。 至2027年底，全…",
