    "content": "7月31日，十四届全国政协第四十八次双周协商座谈会在北京召开，中共中央政治局常委、全国政协主席王沪宁主持会议。人民政协报记者 齐波 摄 本报讯(记者 吕巍)十四届全国政协第四十八次双周协商座谈会7月31日在京召开，中共中央政治局常委、全国政协主席王沪宁主持会议。他表示，中共十八大以来，以习近平同志为核心的中共中央高度重视人工智能发展，把握人工智能技术演进趋势和规律，加强顶层设计和工作部署，出台一系列政策措施，推动我国人工智能综合实力实现整体性、系统性跃升。要深入学习贯彻习近平总书记关于人工智能发展的重要论述，落实中…"
