    "content": "新华社利雅得8月1日电 题：沙特筹建多国联盟能否破解红海航运困局 新华社记者罗晨 尹炣 温新年 沙特阿拉伯日前举办会议，邀请数十个国家和国际组织代表讨论筹建多国海上防卫联盟的倡议，以共同应对红海、曼德海峡和亚丁湾的“海上威胁”。沙特、科威特、巴林等14个国家会后发表联合声明支持这一倡议，沙特方面预计还会有更多国家加入该联合声明。 分析人士认为，沙特推动建立多国海上防卫联盟是基于维护能源运输与国际航运安全的现实需要，也反映出地区国家加强自主安全合作、探索区域安全机制的意愿。不过，联盟能否切实改善区域海上安全局势、是否…"
