    "title": "经济政策一线微观察丨新场景，让消费更有活力",
    "link": "http://www.news.cn/20260801/18c23092d0004d2eb5bfad52d306059c/c.html",
    "pub_date": "2026-08-01 17:32:49",
    "author": "杨仕彦,吴燕霞",
    "description": "2026年是“十五五”开局之年，消费市场正经历悄然变化。产业园屋顶上，年轻人喝着咖啡逛着小店；老电影院里，盖碗轻启茶客围坐谈天；购物中心内，游客在室内森林中驻足拍照……人们来到这些地方不再只为“买东西”，更是为了“享生活”。 消费场景不断“上新”的背后，是消费需求与商业供给的双向奔赴。国家统计局数据显示，上半年，社会消费商品和服务零售总额同比增长2.7%，其中服务零售额增长5.3%，高于商品零售额4.2个百分点。服务消费增速持续领跑商品…",
