    "author": "南方周末研究员 郑颖琦",
    "description": "长三角的产业协同，是各城市凭借自身禀赋在全球产业链重构中抓住机遇、做强核心竞争力，再通过跨城协作建构出紧密的产业生态。 南方周末研究员 郑颖琦 责任编辑：郭倩倩 2026年上半年，我国新型城镇化政策密集落地。首都都市圈规划获批，昆明都市圈成为全国第21个国家级都市圈；国务院发文推动公共服务“跟人走”，交通运输部等十部门联合出台方案，着力健全都市圈综合交通运输体系。 一边是空间上的扩容，一边是制度上的优化，我国都市圈建设正步入规模化落地、…",
    "content": "长三角的产业协同，是各城市凭借自身禀赋在全球产业链重构中抓住机遇、做强核心竞争力，再通过跨城协作建构出紧密的产业生态。 这种高质量的产业协同意味着，每座城市都有稳定的产业税收基础，从根本上提升了地方政府完善公共服务、保障民生福祉的财政能力。 南方周末研究员 郑颖琦 责任编辑：郭倩倩 2026年上半年，我国新型城镇化政策密集落地。首都都市圈规划获批，昆明都市圈成为全国第21个国家级都市圈；国务院发文推动公共服务“跟人走”，交通运输部等十部门联合出台方案，着力健全都市圈综合交通运输体系。 一边是空间上的扩容，一边是制度…"
