    "author": "张继业,李东旭,黄河,栾海",
    "description": "新华社莫斯科/基辅8月1日电（记者黄河 李东旭）俄罗斯国防部1日通报说，7月31日夜间至8月1日凌晨，俄武装力量对乌克兰首都基辅市和基辅州多处军工企业和物流中心进行大规模打击。另据乌克兰媒体1日报道，基辅遭袭已造成多人死伤。 俄国防部在通报中说，俄武装力量使用陆基、海基远程高精度武器和远程攻击型无人机实施了打击。被打击的乌军工企业生产“海王星”“火烈鸟”等多型导弹、无人机、雷达系统、电子对抗设备等。俄方还打击了基辅州一处接收、存储、组装…",
    "content": "新华社莫斯科/基辅8月1日电（记者黄河 李东旭）俄罗斯国防部1日通报说，7月31日夜间至8月1日凌晨，俄武装力量对乌克兰首都基辅市和基辅州多处军工企业和物流中心进行大规模打击。另据乌克兰媒体1日报道，基辅遭袭已造成多人死伤。 俄国防部在通报中说，俄武装力量使用陆基、海基远程高精度武器和远程攻击型无人机实施了打击。被打击的乌军工企业生产“海王星”“火烈鸟”等多型导弹、无人机、雷达系统、电子对抗设备等。俄方还打击了基辅州一处接收、存储、组装无人机的物流中心，以及向乌南部敖德萨港运输军用物资的两艘货船。 另据俄国防部1日…"
