    "author": "周心怡,程思琪",
    "description": "第二十三届中国国际数码互动娱乐展览会（ChinaJoy）于近日在上海举办，为已持续一个月的第二届上海国际游戏动漫月再添新亮点。作为“上海之夏”国际消费季11项标杆活动之一，今年上海国际游戏动漫月活动周期由去年的38天延长至近70天，覆盖暑期消费黄金窗口，为上海数字文娱产业注入持续活力。 作者：周心怡、程思琪、聂雨达 新华社音视频部制作",
