    "content": "为应对当前部分地区生态环境等因素带来的压力，联合国粮食及农业组织等日前呼吁通过促进跨部门和跨学科合作，以综合治理、科学创新、数字技术等方式，践行“全健康”理念，推动全球农业粮食体系可持续发展。 这是记者从日前由联合国粮农组织、南京农业大学等在海南三亚联合主办的“农业粮食体系中的同一健康论坛”上获悉的。 据介绍，“同一健康”即“全健康”，是一种旨在可持续地平衡和优化人类、动物和生态系统健康的理念。这一理念认为人类、动物、植物和环境的健康紧密联系并相互依存，倡导通过跨部门和跨学科合作，帮助各国预防、检测和应对多方面健康…"
