    "content": "新华社内罗毕8月1日电 题：为了和平的使命——记中国驻南苏丹维和部队忠诚履职 新华社记者严钰景 八一建军节之际，在距离祖国万里之遥的南苏丹，中国维和官兵头顶蓝盔、全副武装，奋战在巡逻护卫、工程保障和医疗救助一线，用汗水和忠诚诠释着新时代中国军人的职责使命和大国担当。 对中国赴南苏丹维和官兵而言，今年的建军节分量格外厚重——维和烈士李磊、杨树朋牺牲十周年纪念日刚刚过去。 2016年7月10日，南苏丹首都朱巴爆发严重武装冲突，正在执行警戒任务的李磊、杨树朋所乘步战车突遭炮弹袭击，两人壮烈牺牲，用生命践行了忠实履行使命，…"
