    "title": "三部门调拨1.1万件中央救灾物资支持吉林、黑龙江救灾救助工作",
    "link": "https://www.chinanews.com.cn/gn/2026/08-01/10670448.shtml",
    "pub_date": "2026-08-01 15:21:29",
    "author": "",
    "description": "中新网8月1日电 据应急管理部微信公众号消息，8月1日，国家防灾减灾救灾委员会办公室、应急管理部针对吉林、黑龙江等地近期暴雨洪涝灾害情况，派出工作组赴两省实地查看灾情，协助和指导地方做好救灾工作。根据灾区救灾救助工作需要，会同国家粮食和物资储备局向吉林、黑龙江调拨毛毯、被褥、家庭应急包等1.1万件中央救灾物资，支持地方妥善做好受灾群众安置救助工作。",
    "content": "中新网8月1日电 据应急管理部微信公众号消息，8月1日，国家防灾减灾救灾委员会办公室、应急管理部针对吉林、黑龙江等地近期暴雨洪涝灾害情况，派出工作组赴两省实地查看灾情，协助和指导地方做好救灾工作。根据灾区救灾救助工作需要，会同国家粮食和物资储备局向吉林、黑龙江调拨毛毯、被褥、家庭应急包等1.1万件中央救灾物资，支持地方妥善做好受灾群众安置救助工作。"
