    "content": "新华社北京8月1日电 德国南部巴伐利亚州弗罗伊登贝格附近地区发生林火，截至7月31日，火势仍处于失控状态。当局已部署约330名应急人员投入灭火行动。 安贝格-苏尔茨巴赫地方当局7月31日说，强风肆虐导致火势失控。由于地形复杂，消防人员只能徒步前往各处地点实施灭火作业，雷暴天气也对救援行动造成阻碍。 据德新社报道，当地居民已收到火灾和浓烟警告。当局建议民众避开危险区域，关闭门窗、空调和通风系统，及时收听广播以获取最新消息。 这是7月30日在德国柏林主火车站拍摄的高温警示显示屏。新华社记者张豪夫摄 近期，欧洲多地遭遇今…"
